"""Independent reference checks for files generated by cmd/cli-check; no CLI orchestration."""
import hashlib
import json
from pathlib import Path
import struct
import sys

root = Path(__file__).resolve().parents[1]
out = Path(sys.argv[1]).resolve(strict=True)
assert out.parent == root / 'results' and out.name.startswith('cli-moonbit-')
old = bytes(range(256)) * 8 + b'tail'
new = b'prefix' + old[512:] + old[:512] + b'suffix'
assert (out / '旧文件 空格.bin').read_bytes() == old
assert (out / '新文件.bin').read_bytes() == new
block = bytes(range(256)) * 16
large = block * 2048
assert (out / 'multi-chunk.bin').read_bytes() == large
weak = 1
for byte in block:
    weak = (weak * 0x08104225 + byte) & 0xffffffff
record = struct.pack('>I', weak) + hashlib.blake2b(block, digest_size=32).digest()
assert (out / 'multi-chunk.sig').read_bytes() == struct.pack('>III', 0x72730147, 4096, 32) + record * 2048
assert hashlib.sha256((out / 'large-copy.bin').read_bytes()).digest() == hashlib.sha256(large).digest()
binding = json.loads((out / 'binding.json').read_bytes())
assert binding['schema_version'] == 1 and binding['algorithm'] == 'blake2b-256'
for key, data in [('basis', old), ('target', new), ('delta', (out / '更新.delta').read_bytes())]:
    assert binding[key] == {'size': len(data), 'hash': hashlib.blake2b(data, digest_size=32).hexdigest()}
print(json.dumps({'passed': True, 'oracle': 'Python hashlib/struct',
                  'checks': ['fixture-bytes', '8MiB-signature', '8MiB-copy-sha256', 'binding-identities']}))
